// endpoints/classes/join_POST.ts
async function handle3(request) {
  try {
    const input = schema2.parse(SuperJSON.parse(await request.text()));
    const joinCode = input.joinCode.toUpperCase();
    if (isMemoryMode()) {
      const row2 = memoryClassCodes.find((c) => c.code === joinCode);
      const body2 = row2 ? { valid: true, label: row2.label } : { valid: false };
      return new Response(SuperJSON.stringify(body2));
    }
    const row = await db.selectFrom("classCodes").select(["code", "label"]).where("code", "=", joinCode).executeTakeFirst();
    const body = row ? { valid: true, label: row.label } : { valid: false };
    return new Response(SuperJSON.stringify(body));
  } catch (error) {
    return new Response(
      SuperJSON.stringify({
        error: error instanceof Error ? error.message : "Unknown error"
      }),
      { status: 400 }
    );
  }
}

