// endpoints/auth/login_with_password_POST.ts
import { createHash, timingSafeEqual } from "node:crypto";

// endpoints/auth/login_with_password_POST.schema.ts
var schema3 = external_exports.object({
  email: external_exports.string().email("Email is required"),
  password: external_exports.string().min(1, "Password is required")
});

// endpoints/auth/login_with_password_POST.ts
var MAX_FAILS = 8;
var json = (status, body, headers) => new Response(SuperJSON.stringify(body), { status, headers });
var digest = (s) => createHash("sha256").update(s).digest();
async function handle6(request) {
  try {
    const input = schema3.parse(SuperJSON.parse(await request.text()));
    const email = process.env.LECTURER_EMAIL?.trim().toLowerCase() || "lecturer@salama.ac.ke";
    const password = process.env.LECTURER_PASSWORD || "lecturer123";
    if (!isMemoryMode()) {
      const ip = (request.headers.get("x-forwarded-for") ?? "").split(",")[0].trim() || "unknown";
      const [row] = await sql2`
        select count(*)::int as n from login_attempts
        where ip = ${ip} and success = false
          and attempted_at > now() - interval '15 minutes'`;
      if ((row?.n ?? 0) >= MAX_FAILS) {
        return json(429, { message: "Too many failed attempts. Try again in 15 minutes." });
      }
      const emailOk2 = input.email.trim().toLowerCase() === email;
      const passOk2 = timingSafeEqual(digest(input.password), digest(password));
      const ok2 = emailOk2 && passOk2;
      await sql2`insert into login_attempts (email, success, ip)
                values (${input.email.slice(0, 200)}, ${ok2}, ${ip})`;
      if (!ok2) return json(401, { message: "Incorrect email or password." });
      const token2 = await signSessionToken(email);
      return json(200, { user: lecturerUser(email) }, {
        "Set-Cookie": sessionCookieHeader(token2)
      });
    }
    const emailOk = input.email.trim().toLowerCase() === email;
    const passOk = timingSafeEqual(digest(input.password), digest(password));
    if (!emailOk || !passOk) {
      return json(401, { message: "Incorrect email or password." });
    }
    const token = await signSessionToken(email);
    return json(200, { user: lecturerUser(email) }, {
      "Set-Cookie": sessionCookieHeader(token)
    });
  } catch (error) {
    if (error instanceof ZodError) {
      return json(400, { message: "Email and password are required." });
    }
    return json(500, {
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
}

